mapper.select:
select  ROW_NUMBER() OVER (ORDER BY type) AS temp_id,a.id,a.userName,a.password,a.type,a.email,a.status,a.create_time,a.update_time
from system_user a


    and a.is_deleted = 0

        and a.id=#{condition.id}


        and a.username like concat('%',#{condition.username},'%')


        and a.type=#{condition.type}


        and a.email=#{condition.email}


        and a.status=#{condition.status}


        and create_time>=#{condition.createTime}


        and a.update_time>=#{condition.updateTime}




order by type
